window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"66sKwPBNaVM","speaker":"Mohamed Younis Menfi","role":"President","country":"Libya","region":"Middle East","url":"https://www.youtube.com/watch?v=66sKwPBNaVM","date":"20260923","title":"🇱🇾 Libya - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1119,"words":2404,"counts":{"claims":28,"promises":2,"attacks":0},"topics":[{"topic":"Libya sovereignty","share":0.1143,"seconds":128},{"topic":"Sahel terrorism","share":0.0754,"seconds":84},{"topic":"Libya sanctions","share":0.0669,"seconds":75},{"topic":"Palestine statehood","share":0.0645,"seconds":72},{"topic":"Libya elections","share":0.0632,"seconds":71},{"topic":"State sovereignty","share":0.0584,"seconds":65},{"topic":"Libya diplomacy","share":0.0575,"seconds":64},{"topic":"Libya ceasefire","share":0.0573,"seconds":64},{"topic":"Global governance","share":0.0569,"seconds":64},{"topic":"UN peacekeeping","share":0.056,"seconds":63},{"topic":"Libya mediation","share":0.056,"seconds":63},{"topic":"Israel-Gaza conflict","share":0.0555,"seconds":62},{"topic":"UN Security Council","share":0.0552,"seconds":62},{"topic":"Sudan civil war","share":0.0547,"seconds":61},{"topic":"Mediterranean security","share":0.0542,"seconds":61},{"topic":"Libya political unity","share":0.0538,"seconds":60}],"timeline":[[2,62,null],[64,128,"Global governance"],[130,202,"Palestine statehood"],[203,265,"Israel-Gaza conflict"],[266,328,"Sudan civil war"],[328,413,"Sahel terrorism"],[414,474,"Mediterranean security"],[476,541,"State sovereignty"],[544,605,"Libya sovereignty"],[606,681,"Libya sanctions"],[682,747,"Libya diplomacy"],[748,808,"Libya political unity"],[808,879,"Libya elections"],[881,943,"Libya mediation"],[945,1009,"Libya ceasefire"],[1010,1071,"UN Security Council"],[1072,1135,"UN peacekeeping"],[1136,1203,"Libya sovereignty"],[1204,1229,null]],"stances":{"Global governance":"Mohamed Younis Menfi calls for an international order where the rule of law is an equal right and cooperation is a genuine partnership.","Palestine statehood":"Mohamed Younis Menfi states that the Palestinian people's plight is worsening due to occupation and repression, yet they remain steadfast in their rights guaranteed by international law.","Israel-Gaza conflict":"Mohamed Younis Menfi states that the conflict in Palestine is driving regional instability and extremism, while affirming full solidarity with Saudi Arabia against attacks on its security and holy sites.","Sudan civil war":"Mohamed Younis Menfi states that the ongoing armed conflict in Sudan is a devastating war causing heavy losses for its people and endangering regional security.","Sahel terrorism":"Mohamed Younis Menfi asserts that the Sahel region is a central part of Africa's future and that its security is integral to Libya's own stability, rejecting the notion of it being merely a resource source or a footnote in global affairs.","Mediterranean security":"Libya views the Mediterranean as a shared space for connection and development rather than a barrier, leveraging its unique Arab, African, and Islamic identity to foster trade, energy transition, and security.","State sovereignty":"Mohamed Younis Menfi argues that a state vacuum leads to the loss of national decision-making independence and that true sovereignty requires functional judicial and oversight institutions.","Libya sovereignty":"Mohamed Younis Menfi defines sovereignty as ensuring free national decision-making, transparency in UN cooperation, protection of Libyan rights, state institutions stronger than individuals, and preventing corruption.","Libya sanctions":"Mohamed Younis Menfi calls for the UN Security Council to implement resolutions and sanctions without selectivity or double standards, ensuring accountability for documented violations.","Libya diplomacy":"Mohamed Younis Menfi states that Libya's external relations should be based on national interests, mutual respect, and sovereignty rather than replacing one foreign influence with another.","Libya political unity":"Mohamed Younis Menfi argues that Libya requires a unified sovereign state with legitimate institutions rather than continued crisis management or foreign influence.","Libya elections":"Mohamed Younis Menfi asserts that legitimacy in Libya must derive from the people through constitutional mechanisms and free elections, rejecting temporary deals and outlining four governing principles for any sustainable political process.","Libya mediation":"Mohamed Younis Menfi asserts that international mediation must respect Libyan national ownership, avoid external imposition, and ensure inclusive, transparent, and accountable processes.","Libya ceasefire":"Mohamed Younis Menfi asserts that sustainable legitimacy requires adherence to national legal frameworks and the will of the people, leading to the announcement of a new committee for deescalation.","UN Security Council":"Mohamed Younis Menfi announces Libya's candidacy for the UN Security Council and outlines its potential role in regional stability.","UN peacekeeping":"Mohamed Younis Menfi states that Libya seeks a seat at the UN to contribute to global justice and stability rather than merely occupying a position, urging partners to base their interests on Libya's stability and partnership."},"claims":[{"t":148,"quote":"That reality unfolds before us at every moment in Palestine whose delegation we regret has not been able to participate with us in this There the plight of the Palestinian people continues to worsen after decades of occupation, repression, and alteration of their identity.","topic":"Palestine statehood","kind":"fact"},{"t":244,"quote":"Its repercussions have extended to the Arabian Gulf most recently in the attack against the Kingdom of Saudi Arabia.","topic":"Israel-Gaza conflict","kind":"fact"},{"t":279,"quote":"The ongoing armed conflict in the Sudan, our brotherly neighbor, has made its people the victims of a devastating war for which they are paying a hefty price.","topic":"Sudan civil war","kind":"fact"},{"t":291,"quote":"In that war, interests and interventions collide and its effects extend beyond the borders of Sudan, endangering the security and stability of the region and the unity of its states.","topic":"Sudan civil war","kind":"fact"},{"t":304,"quote":"The instability in the Sahel represents an existential threat to the integrity of states.","topic":"Sudan civil war","kind":"fact"},{"t":360,"quote":"Decades ago, an African will emerge from the Libyan city of Cert that contributed to the establishment of the African Union.","topic":"Sahel terrorism","kind":"fact"},{"t":414,"quote":"Likewise, we view the Mediterranean basin not as a barrier between Africa and Europe, but as a shared space of for connection.","topic":"Mediterranean security","kind":"fact"},{"t":423,"quote":"Relations among its countries should move from from beyond merely managing migration and crisis towards making the Mediterranean a bridge for development, trade, energy transition, investment, and common security.","topic":"Mediterranean security","kind":"fact"},{"t":436,"quote":"Ladies and gentlemen, geographically and politically, Libya stands at the meeting point of these It is Arab in its identity and language. African in its geography, destiny and in an intrinsic part of its culture, interests and partnerships, and Islamic in its civilizational values which incline towards peace, security, and building bridges with its neighbors.","topic":"Mediterranean security","kind":"fact"},{"t":483,"quote":"When the state the vacuum does not remain empty. Competing interests fill it. Armed groups become active within it. Criminal and smuggling networks spread, illicit funds seep in and institutions themselves become arenas of struggle for At that point, the state does not merely lose part of its security. Its national decision-m begins to lose its independence.","topic":"State sovereignty","kind":"fact"},{"t":525,"quote":"Sovereignty is not merely a flag raised or borders drawn on maps. Nor is its slogans while judicial and oversight institutions fail to exercise the roles independently and responsibly.","topic":"State sovereignty","kind":"fact"},{"t":544,"quote":"means that national decision making is free. It also means that our cooperation and integration with United Nations bodies are based on transparency, seriousness and impartiality, free from selectivity and double standards.","topic":"Libya sovereignty","kind":"fact"},{"t":561,"quote":"Sovereignty means protecting the rights and dignity of the Libyan people from violations whoever the perpetrator and ensuring that no one is above the law and no one escapes accountability.","topic":"Libya sovereignty","kind":"fact"},{"t":578,"quote":"Sovereignty means that state institutions are stronger than individuals and groups and that weapons are subject to the law.","topic":"Libya sovereignty","kind":"fact"},{"t":587,"quote":"It also means that the country's wealth remains the property of the people, not spoils to be divided among parties, networks of interest or dubious partnerships that some sort of custodianship over the state.","topic":"Libya sovereignty","kind":"fact"},{"t":627,"quote":"This includes the report of the panel of experts on violations and cases of non-compliance.","topic":"Libya sanctions","kind":"fact"},{"t":695,"quote":"Libya paid a heavy price when regional and international balances of power were transformed into balances within its own territory.","topic":"Libya diplomacy","kind":"fact"},{"t":788,"quote":"after years of political division and polarization that have drained the state and society, Libya no longer needs more crisis management","topic":"Libya political unity","kind":"fact"},{"t":819,"quote":"The people are the source of legitimacy and it is they who can give institutions their unity","topic":"Libya elections","kind":"fact"},{"t":827,"quote":"Temporary deals cannot do so nor can fragile settlements that collapse whenever the balance of power shifts or loyalties change","topic":"Libya elections","kind":"fact"},{"t":893,"quote":"The will of Libyans is the foundation and the inclusion of all the different parties without exclusion or imposition is the true guarantee of the sustainability of any solution.","topic":"Libya mediation","kind":"fact"},{"t":945,"quote":"Experience has taught us that fragile settlements can begin to unravel as soon as the balance of power shifts or their outcomes emerge.","topic":"Libya ceasefire","kind":"fact"},{"t":954,"quote":"Any arrangements that disregard national legal frameworks expose themselves to challenge and dispute. They reproduce the crisis rather than end it.","topic":"Libya ceasefire","kind":"fact"},{"t":1045,"quote":"From this rostrm, Libya announces its candidacy for the membership of the security council for the term 2028 2029 for the African seat.","topic":"UN Security Council","kind":"fact"},{"t":1072,"quote":"It embodies a national will for Libya to regain its natural role in the international arena and to shoulder its responsibility for the maintenance of international peace and security.","topic":"UN peacekeeping","kind":"fact"},{"t":1099,"quote":"Libya does not seek the seat merely to occupy a position.","topic":"UN peacekeeping","kind":"fact"},{"t":1136,"quote":"We Libyans bear the the primary responsibility.","topic":"Libya sovereignty","kind":"fact"},{"t":1143,"quote":"Patriotism is not only the defense of sovereignity against negative foreign interference. It also is the protection of the state from corruption within the safeguarding of public funds, the upholding of the rule of law and the placing the nation above power and self-interest.","topic":"Libya sovereignty","kind":"fact"}],"promises":[{"t":984,"quote":"we announce from this rostrm the launch of work on a national committee for deescalation and confidence building.","topic":"Libya ceasefire","kind":"promise"},{"t":992,"quote":"The committee will draw on national and local initiatives. It will aim to prevent no conflicts, contain escalation and prevent its recurrence.","topic":"Libya ceasefire","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":null,"text":"The assembly will hear an address by His Excellency Mr. Muhammad Eunis President of the Presidential Council of the State of Libya. I request protocol to escort his and invite him to address the assembly. &gt;&gt; your excellency Dr. Haliv Rahman, President of the General Assembly of the United Nations. Your Excellency, Mr. Antonio Guterish, Secretary General of the United Nations."},{"t":64,"topic":"Global governance","text":"Ladies and gentlemen, we meet today as the world undergoes a profound transformation not only in the balance of power, but in the very concept of power and the ethics of its use. This transformation is reshaping the meaning of security, the nature of alliances and the capacity of the international order to uphold the foundations and principles upon which and for which it was established. At the heart of these transformations lies a question that transcends the borders of states and continents. How can we build an international order in which the rule of law is an equal right, not a privilege of the most powerful? And how can we make cooperation a genuine partnership among nations rather than a carving up of spheres of influence?"},{"t":130,"topic":"Palestine statehood","text":"We in the Arab and Islamic world and on our African continent do not approach this question as observers for we live its consequences every day. That reality unfolds before us at every moment in Palestine whose delegation we regret has not been able to participate with us in this There the plight of the Palestinian people continues to worsen after decades of occupation, repression, and alteration of their identity. Yet they remain steadfast in their adherence to their right to life and to These are rights guaranteed without discrimination by international law and international humanitarian law. All of for international instruments and to move from texts and promises to a reality and for the right of the Palestinian people to their state to be realized in accordance with international law."},{"t":203,"topic":"Israel-Gaza conflict","text":"The continued undermining of these prospects for its establishment not only squanders opportunities for peace, it also drives the region towards a widening cycle of conflict, the spread of extremism and a search for alternatives amid major expansionist projects that extend beyond occupied Palestine to Syria and Lebanon. Neither the Islamic and Christian holy sites nor civilian and infra nor nor civilians and civilian infrastructure in Palestine have been spared the ravages of this conflict. Its repercussions have extended to the Arabian Gulf most recently in the attack against the Kingdom of Saudi Arabia. We affirm our full solidarity with the Kingdom of Saudi Arabia in safeguarding its security, its territorial integrity, its citizens and its holy sites. We reject any targeting that threatens it or endangers Islamic holy sites."},{"t":266,"topic":"Sudan civil war","text":"The security of the kingdom and the Gulf given their Arab and Islamic weight is not a national matter, but it is a pillar of the security and stability of our region. The ongoing armed conflict in the Sudan, our brotherly neighbor, has made its people the victims of a devastating war for which they are paying a hefty price. In that war, interests and interventions collide and its effects extend beyond the borders of Sudan, endangering the security and stability of the region and the unity of its states. The instability in the Sahel represents an existential threat to the integrity of states. That threat stems from the nexus of terrorism, organized crime, poverty, climate change, displacement, and migration, and from the widening of the cycle of armed conflict in the region."},{"t":328,"topic":"Sahel terrorism","text":"It is no longer acceptable for the world to regard the Sahel merely as a source of resources and arena for international competition or a footnote in global decision-making. Africa, whose journey we have followed since the founding of the African Union, is not the margin of the world. It is one of the centers of the world to come. Libya does not lie on the edge of Africa. Libya is of Africa, of its history, of its security, and of its future. Decades ago, an African will emerge from the Libyan city of Cert that contributed to the establishment of the African Union. That fact reminds us that Libya has never been merely a bridge between Africa and the Mediterranean, but a partner in shaping the African project We therefore view the security of the Sahil region as part of Libya's own security and stability. We view the security and stability of the states of the region and all our African neighbors near and far together with development Africa all as investment in the common security of Africa and its European This is not assistance provided by one party to another, nor is it a responsibility born by one party alone."},{"t":414,"topic":"Mediterranean security","text":"Likewise, we view the Mediterranean basin not as a barrier between Africa and Europe, but as a shared space of for connection. Relations among its countries should move from from beyond merely managing migration and crisis towards making the Mediterranean a bridge for development, trade, energy transition, investment, and common security. Ladies and gentlemen, geographically and politically, Libya stands at the meeting point of these It is Arab in its identity and language. African in its geography, destiny and in an intrinsic part of its culture, interests and partnerships, and Islamic in its civilizational values which incline towards peace, security, and building bridges with its neighbors. The multiplicity of these circles is not a contradiction but a source of strength, responsibility and opportunity."},{"t":476,"topic":"State sovereignty","text":"From this geopolitical vantage point in particular, we have learned a harsh lesson in recent years. When the state the vacuum does not remain empty. Competing interests fill it. Armed groups become active within it. Criminal and smuggling networks spread, illicit funds seep in and institutions themselves become arenas of struggle for At that point, the state does not merely lose part of its security. Its national decision-m begins to lose its independence. This brings us to the essence of what sovereignty means to us. Sovereignty is not merely a flag raised or borders drawn on maps. Nor is its slogans while judicial and oversight institutions fail to exercise the roles independently and responsibly."},{"t":544,"topic":"Libya sovereignty","text":"means that national decision making is free. It also means that our cooperation and integration with United Nations bodies are based on transparency, seriousness and impartiality, free from selectivity and double standards. Sovereignty means protecting the rights and dignity of the Libyan people from violations whoever the perpetrator and ensuring that no one is above the law and no one escapes accountability. Sovereignty means that state institutions are stronger than individuals and groups and that weapons are subject to the law. It also means that the country's wealth remains the property of the people, not spoils to be divided among parties, networks of interest or dubious partnerships that some sort of custodianship over the state. Sovereignty means preventing corrupt money from buying influence."},{"t":606,"topic":"Libya sanctions","text":"It means preventing influence from becoming an immunity that shields corrupt money. If that cycle becomes entrenched, it weakens the state from within and threatens the survival of its institutions. In this context, we call upon the security council to discharge its responsibilities and to follow up on the United Nations reports submitted to it. This includes the report of the panel of experts on violations and cases of non-compliance. We call upon the council to give serious consideration to the panel's recommendations and to take the necessary action within its established mandates. The purpose is to ensure the effective implementation of the council resolutions and the relevant sanctions measures without selectivity or double standards. Documented violations should not become mere recurring facts in Nor should accountability end at documentation. The authority of international law and the credibility of its institutions are measured by their to move from monitoring violations to holding perpetrators accountable and from resolution to implementation for all without exception."},{"t":682,"topic":"Libya diplomacy","text":"Sovereignty also means that the state's ex foreign relations are an extension of its national interests, not an extension of others conflicts within it. Mr. President, Libya paid a heavy price when regional and international balances of power were transformed into balances within its own territory. Accordingly, our vision for Libya's external relations is clear. We do not seek to replace one influence with another, one access with another, or one dependency with another. We want strong relations with our Arab especially our neighboring countries. We want Libya to regain its natural role within its African continent. We want balanced strategic partnerships with our neighbors and our regional international sphere based on a single principle, namely common interests, mutual respect, and respect for national sovereignty."},{"t":748,"topic":"Libya political unity","text":"Libya's true ally is not one who seeks out the strongest party within it. The true ally is one who wants a strong Libyan state. The true partner is not one whose interests are tied to the continuation of the vision. The true partner is one whose shared interest with us grows as Libya becomes more united, stable, and prosperous. We want states to compete in Libya on investment, reconstruction, energy, technology, and development, not for influence within its institutions. Ladies and gentlemen, after years of political division and polarization that have drained the state and society, Libya no longer needs more crisis management, but rather the will to end the crisis. Our goal is clear. A unified sovereign state whose institutions derive their legitimacy from the will of its people."},{"t":808,"topic":"Libya elections","text":"The path to that goal is a return to the people through constitutional and legal mechanisms. referendums and free and fair elections. The people are the source of legitimacy and it is they who can give institutions their unity and Temporary deals cannot do so nor can fragile settlements that collapse whenever the balance of power shifts or loyalties change. Here we welcome the effort and intention of every state sincerely seeking to end the political and institutional division. We also appreciate the role entrusted to the United Nations support mission in Libya and its responsibility for facilitating the political process. Nevertheless, past experience obliged us to be clear. Any subst any sustainable political process must not violate four governing principles. First, respect for legitimacy and for the constitutional and legal frameworks in force without circumventing them or creating political arrangements outside established frameworks and procedures."},{"t":881,"topic":"Libya mediation","text":"Second, the principle of national ownership is a red line. International mediation must not turn into custodianship or into solutions crafted from abroad. The will of Libyans is the foundation and the inclusion of all the different parties without exclusion or imposition is the true guarantee of the sustainability of any solution. Third, ensuring equal opportunities for all parties as well as rejecting the use of force, influence or effect play to impose predetermined political outcomes. Fourth, commitment to transparency in understandings and This requires defining the phases of implementation, their timelines, and the entities responsible for them. It also requires establishing clear mechanisms for oversight and accountability so as to ensure outcomes that are implementable, legally sound, and capable of producing legitimate and stable institutions."},{"t":945,"topic":"Libya ceasefire","text":"Experience has taught us that fragile settlements can begin to unravel as soon as the balance of power shifts or their outcomes emerge. Any arrangements that disregard national legal frameworks expose themselves to challenge and dispute. They reproduce the crisis rather than end it. Sustainable legitimacy and legality are not created by a feticon plea, nor are they protected by shifting balances of power. They are created by the will of the people and protected by the law. In translating these principles into national responsibility and concrete we announce from this rostrm the launch of work on a national committee for deescalation and confidence building. The committee will draw on national and local initiatives. It will aim to prevent no conflicts, contain escalation and prevent its recurrence. This is in addition to supporting reconciliation and creating a safe environment for the political and electoral process."},{"t":1010,"topic":"UN Security Council","text":"Here we call upon all Libyan parties to engage in this framework. We also call upon the UN and Libya's partners to support and facilitate it with full respect for sovereignty and national ownership. Ladies and gentlemen, a Libya that regains its sovereignty and the unity of its institutions will not be a gain for Libyans alone. It will be a force for stability in the Arab world, a source of strategic depth for security and development in Africa, a responsible partner in the Mediterranean, and a bridge for cooperation between north and south. From this rostrm, Libya announces its candidacy for the membership of the security council for the term 2028 2029 for the African seat. Its campaign is conducted under the slogan consolidating justice for security and peace. Libya a bridge among nations. Libya looks forward to the confidence and support of the member states in this endeavor. This candidacy is not merely a diplomatic ambition."},{"t":1072,"topic":"UN peacekeeping","text":"It embodies a national will for Libya to regain its natural role in the international arena and to shoulder its responsibility for the maintenance of international peace and security. It stems from a firm conviction that peace is built on not merely on the absence of conflict but on establishing justice and addressing the causes of injustice and Libya does not seek the seat merely to occupy a position. Rather, it seeks to contribute to building a more equitable international order and to serve as a bridge among nations, a voice for consensus and an active partner in peacemaking. Hence, our message to our friends and partners is not that they should abandon their interests in Libya, but that they should build those interests with us on a firmer foundation. Namely, that their interests lie in Libya's stability, not in the fragility of its institutions and in partnership with Libya, not in influence within it."},{"t":1136,"topic":"Libya sovereignty","text":"We Libyans bear the the primary responsibility. Patriotism is not only the defense of sovereignity against negative foreign interference. It also is the protection of the state from corruption within the safeguarding of public funds, the upholding of the rule of law and the placing the nation above power and self-interest. Libya today has an opportunity to leave behind the cycle of transitional phases and to enter the era of the state. It has an opportunity to regain the role befitting its history, its position, and its standing among nations. Libya does not want to be an arena on whose soil the interests of others are balanced, but a state that shapes its own balance by its own will. It does not want others to compete for influence within it, but to compete for partnership with it. That is the path we choose for Libya. A state sovereign in its decisions, unified in its institutions, just among its citizens and a partner for peace and stability in its region and the world."},{"t":1204,"topic":null,"text":"That is the right of our people, our responsibility towards them and our trust to future generations. May the peace and mercy and blessings of Allah be upon you. On behalf of the general assembly, I wish to thank the president of the presidential council of the state of"}],"compare":[{"topic":"Libya","share":0.1719,"mean":0.0019,"rank":1,"others":5},{"topic":"Israel–Palestine","share":0.1201,"mean":0.052,"rank":26,"others":76},{"topic":"International Law & Order","share":0.1153,"mean":0.0601,"rank":39,"others":102},{"topic":"UN & its reform","share":0.1112,"mean":0.2052,"rank":138,"others":170},{"topic":"Africa","share":0.0754,"mean":0.0232,"rank":28,"others":36},{"topic":"Sudan","share":0.0547,"mean":0.007,"rank":12,"others":15},{"topic":"Middle East","share":0.0542,"mean":0.0071,"rank":13,"others":19}]};
